"""GCU400 specialization of ``aten::_cudnn_rnn_flatten_weight``.

The shared implementation gathers the copy plan (source address, destination
offset, length) into an int64 device descriptor and lets one kernel dereference
the addresses.  ``torch_gcu`` narrows a Long tensor to Int when it is
transferred to the device (unless int64 is explicitly enabled), so the 64-bit
source addresses were truncated and the kernel dereferenced garbage -- the very
first call died with a device ``Sip exception``.

This version keeps the same single-launch shape but transports the addresses as
two int32 halves (``lo = addr & 0x7FFFFFFF``, ``hi = addr >> 31``) and
reassembles them with 64-bit integer arithmetic inside the kernel, then casts
the result to a pointer.  No int64 *tensor* is involved, so the transfer is
exact whatever the int64 enablement flag says, and the whole flatten -- every
weight matrix, every bias, every cuDNN-reserved zero slot -- still completes in
one kernel launch.  A slot that has to stay zero is encoded as a run with a null
source address and filled by the kernel itself.

Everything else (plan construction, canonical-storage fast path, weight
rebinding, ``.out`` semantics) is unchanged from the shared implementation.
"""

import logging

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn

logger = logging.getLogger(__name__)

# cudnnRNNMode_t: RNN_RELU=0, RNN_TANH=1, LSTM=2, GRU=3
# The number of "gates" decides how many rows each linear layer matrix has.
_NUM_GATES = {
    0: 1,  # RNN_RELU
    1: 1,  # RNN_TANH
    2: 4,  # LSTM
    3: 3,  # GRU
}

# Weights can be of any 1/2/4-byte dtype and the copy is dtype agnostic because
# it is a plain element-wise copy.  8-byte elements (float64/int64) stay
# rejected: torch_gcu narrows 64-bit integers on the way to the device unless
# int64 is explicitly enabled, so that path cannot be relied on.
_SUPPORTED_ELEM_SIZES = (1, 2, 4)

# Each copy run of the flat plan is described by 6 int32 words:
#   src_lo, src_hi     -- 31-bit halves of the source element address (0 = fill)
#   dst_lo, dst_hi     -- 31-bit halves of the destination buffer address
#   dst_off            -- element offset of the slot inside the destination
#   n_elems            -- element count of the slot
_PLAN_WORDS = 6
# Each copy run of the strided plan appends three words describing the source
# layout as a (rows, cols) tile, which covers every 1-D/2-D weight view.
_STRIDED_PLAN_WORDS = 9

# Flat copy runs are one tile of BLOCK elements per (persistent) program step;
# 32768 elements per tile was the fastest tile width for the streaming copy
# shapes this operator sees (a few hundred KiB up to tens of MiB).
_COPY_BLOCK = 32768
_COPY_NUM_WARPS = 2
# The copy already saturates the memory system with a handful of programs per
# SIP; more programs only add launch overhead.
_COPY_GRID_CAP = 48


@triton.jit(do_not_specialize=["num_runs"])
def _flat_copy_plan_kernel(plan_ptr, ref_ptr, num_runs, BLOCK: tl.constexpr):
    """Copy every run of the flat plan; runs with a null source are zeroed.

    ``ref_ptr`` only fixes the element type of the copy (the dtype of the flat
    weight buffer); every address actually used comes from the int32 plan.
    """
    elem_ty = ref_ptr.dtype.element_ty
    pid = tl.program_id(0)
    num_pids = tl.num_programs(0)
    # Plan stride is 6 words: src_lo, src_hi, dst_lo, dst_hi, dst_off, n_elems.
    for run in tl.range(0, num_runs):
        base = plan_ptr + run * 6
        src_lo = tl.load(base + 0)
        src_hi = tl.load(base + 1)
        dst_lo = tl.load(base + 2)
        dst_hi = tl.load(base + 3)
        dst_off = tl.load(base + 4)
        n_elems = tl.load(base + 5)
        # Fold the 31-bit halves back into one address, then reinterpret it as a
        # pointer.  2**31 == 2147483648.
        dst_addr = dst_hi.to(tl.int64) * 2147483648 + dst_lo.to(tl.int64)
        dst_ptr = tl.cast(dst_addr, tl.pointer_type(elem_ty)) + dst_off
        tile_count = tl.cdiv(n_elems, BLOCK)
        if src_lo == 0 and src_hi == 0:
            zeros = tl.zeros([BLOCK], dtype=elem_ty)
            for tile_id in tl.range(pid, tile_count, num_pids):
                offs = tile_id * BLOCK + tl.arange(0, BLOCK)
                tl.store(dst_ptr + offs, zeros, mask=offs < n_elems)
        else:
            src_addr = src_hi.to(tl.int64) * 2147483648 + src_lo.to(tl.int64)
            src_ptr = tl.cast(src_addr, tl.pointer_type(elem_ty))
            for tile_id in tl.range(pid, tile_count, num_pids):
                offs = tile_id * BLOCK + tl.arange(0, BLOCK)
                mask = offs < n_elems
                tl.store(dst_ptr + offs, tl.load(src_ptr + offs, mask=mask), mask=mask)


@triton.jit(do_not_specialize=["num_runs"])
def _strided_copy_plan_kernel(plan_ptr, ref_ptr, num_runs, BLOCK: tl.constexpr):
    """Same plan traversal, but the source is a (rows, cols) tile with strides.

    Only used when a weight is not contiguous; contiguous weights (all of the
    real RNN flat weights) go through the flat kernel above, which keeps the
    innermost dimension unit-stride and therefore vectorized.
    """
    elem_ty = ref_ptr.dtype.element_ty
    pid = tl.program_id(0)
    num_pids = tl.num_programs(0)
    # Plan stride is 9 words: the 6 flat words followed by row_stride,
    # col_stride, n_rows.
    for run in tl.range(0, num_runs):
        base = plan_ptr + run * 9
        src_lo = tl.load(base + 0)
        src_hi = tl.load(base + 1)
        dst_lo = tl.load(base + 2)
        dst_hi = tl.load(base + 3)
        dst_off = tl.load(base + 4)
        n_cols = tl.load(base + 5)
        row_stride = tl.load(base + 6)
        col_stride = tl.load(base + 7)
        n_rows = tl.load(base + 8)
        dst_addr = dst_hi.to(tl.int64) * 2147483648 + dst_lo.to(tl.int64)
        dst_ptr = tl.cast(dst_addr, tl.pointer_type(elem_ty)) + dst_off
        src_addr = src_hi.to(tl.int64) * 2147483648 + src_lo.to(tl.int64)
        src_ptr = tl.cast(src_addr, tl.pointer_type(elem_ty))
        tile_count = tl.cdiv(n_cols, BLOCK)
        for row in tl.range(0, n_rows):
            row_dst = dst_ptr + row * n_cols
            row_src = src_ptr + row * row_stride
            for tile_id in tl.range(pid, tile_count, num_pids):
                cols = tile_id * BLOCK + tl.arange(0, BLOCK)
                mask = cols < n_cols
                if src_lo == 0 and src_hi == 0:
                    tl.store(
                        row_dst + cols,
                        tl.zeros([BLOCK], dtype=elem_ty),
                        mask=mask,
                    )
                else:
                    tl.store(
                        row_dst + cols,
                        tl.load(row_src + cols * col_stride, mask=mask),
                        mask=mask,
                    )


def _split_addr(addr):
    """Split an integer address into two non-negative 31-bit halves."""
    return addr & 0x7FFFFFFF, addr >> 31


def _build_copy_plan(
    weight_arr,
    weight_stride0,
    input_size,
    mode,
    hidden_size,
    proj_size,
    num_layers,
    bidirectional,
):
    """Reproduce the cuDNN flat-weight layout as a list of copy runs.

    The flat buffer holds, for every (layer, direction) group, the input
    matrices followed by the recurrent matrices (and the projection matrix for
    projected LSTMs); all biases of all groups are appended at the very end.
    """
    if mode not in _NUM_GATES:
        raise RuntimeError(f"cudnn_rnn_flatten_weight: unsupported mode {mode}")
    if num_layers < 1:
        raise RuntimeError(
            f"cudnn_rnn_flatten_weight: num_layers must be >= 1, got {num_layers}"
        )

    gates = _NUM_GATES[mode]
    num_dirs = 2 if bidirectional else 1
    has_proj = proj_size > 0
    # Width of the recurrent matrices, which is also the input width of every
    # layer except the first one.
    hidden_out = proj_size if has_proj else hidden_size
    num_weights = 2 + (1 if has_proj else 0)
    has_bias = weight_stride0 - num_weights == 2
    if not has_bias and weight_stride0 != num_weights:
        raise RuntimeError(
            "cudnn_rnn_flatten_weight: weight_stride0 "
            f"({weight_stride0}) does not match a weights-only ({num_weights}) "
            f"or weights-and-biases ({num_weights + 2}) group"
        )

    num_groups = num_layers * num_dirs
    if len(weight_arr) < num_groups * weight_stride0:
        raise RuntimeError(
            "cudnn_rnn_flatten_weight: number of layers mismatch, got "
            f"{len(weight_arr)} tensors for {num_groups} layer groups of "
            f"{weight_stride0} tensors"
        )

    # With biases the projection matrix is the last element of a group,
    # without biases it directly follows the two weight matrices.
    proj_slot = 4 if has_bias else 2

    runs = []
    offset = 0
    for group in range(num_groups):
        layer = group // num_dirs
        in_size = input_size if layer == 0 else num_dirs * hidden_out
        sizes = [gates * hidden_size * in_size, gates * hidden_size * hidden_out]
        if has_proj:
            sizes.append(proj_size * hidden_size)
        for k, size in enumerate(sizes):
            src = group * weight_stride0 + (k if k < 2 else proj_slot)
            runs.append((src, offset, size))
            offset += size

    bias_size = gates * hidden_size
    for group in range(num_groups):
        for k in (2, 3):
            if has_bias:
                runs.append((group * weight_stride0 + k, offset, bias_size))
            else:
                runs.append((-1, offset, bias_size))
            offset += bias_size

    for src, _, size in runs:
        if src < 0:
            continue
        if weight_arr[src].numel() != size:
            raise RuntimeError(
                "cudnn_rnn_flatten_weight: weight "
                f"{src} has {weight_arr[src].numel()} elements but the cuDNN "
                f"flat layout expects {size}"
            )

    return runs, offset


def _canonical_base(weight_arr, runs, total):
    """Return the first weight if all weights already tile one flat storage.

    ``nn.RNNBase.flatten_parameters()`` runs on every ``forward()``, so after
    the first flatten the weights are contiguous views into one flat buffer,
    each sitting exactly at the offset the copy plan assigns it.  In that state
    the flat buffer *is* the input storage, so there is nothing to copy and
    nothing to rebind.

    The check uses ``storage_offset`` and raw element pointers (both cheap C
    calls, no Python storage object per weight), because this path has to stay
    cheap: it is the steady state of ``flatten_parameters()``.  The offset is
    also what makes the check sound: freshly allocated tensors are often laid
    out back to back, so matching addresses alone would treat a set of separate
    allocations as one buffer, while a weight that really views the flat buffer
    sits at exactly its plan offset inside it.
    """
    base_ptr = None
    elem_size = None
    next_dst = 0
    for src, dst, size in runs:
        if size == 0:
            continue
        # The runs must tile the whole buffer in plan order; otherwise the
        # input storage is not the flat buffer.
        if dst != next_dst:
            return None
        next_dst += size
        if src < 0:
            # A reserved bias slot.  It must stay zero in the flat buffer, and
            # in a buffer produced by this operator it already is.
            continue
        w = weight_arr[src]
        if not w.is_contiguous() or w.numel() != size or w.storage_offset() != dst:
            return None
        ptr = w.data_ptr()
        if base_ptr is None:
            base_ptr = ptr - dst * w.element_size()
            elem_size = w.element_size()
        elif ptr != base_ptr + dst * elem_size:
            return None
    if base_ptr is None or next_dst != total:
        return None
    return weight_arr[runs[0][0]]


def _rebind_weights(weight_arr, runs, out, total):
    """Point every weight at its slot inside the flat ``out`` buffer.

    This mirrors the reference operator's ``set_orig_weights_to_flat_buf`` step
    (PyTorch ``cudnn/RNN.cpp``): after the call each ``weight_arr[i]`` is a view
    into the flat buffer instead of its original storage.
    """
    if total == 0:
        return
    out_storage = out.untyped_storage()
    # ``set_`` on a leaf that requires grad is an in-place op, so it must run
    # under no_grad; ``nn.RNNBase.flatten_parameters`` does the same around its
    # call into the reference operator.
    with torch.no_grad():
        for src, dst, size in runs:
            if src < 0 or size == 0:
                continue
            w = weight_arr[src]
            if w.is_contiguous():
                # The slot is contiguous by construction, so the weight's own
                # strides describe it exactly.
                w.set_(out_storage, dst, w.shape, w.stride())
            else:
                # Same layout as the reference's ``view_as``: reshape the flat
                # slot so a non-contiguous weight keeps its logical element
                # order.
                w.set_(out.narrow(0, dst, size).reshape(w.shape))


def _append_run(plan_words, source, dst_addr, dst_off, contiguous):
    """Append the run(s) that copy ``source`` into slot ``dst_off``.

    Contiguous sources collapse into a single flat run.  A non-contiguous source
    is described as one (rows, cols) tile when it is at most 2-D, and as one
    tile per leading index otherwise -- that keeps the kernel free of any
    per-element index math on the (never taken) strided path.
    """
    if contiguous:
        dst_lo, dst_hi = _split_addr(dst_addr)
        src_lo, src_hi = _split_addr(source.data_ptr())
        plan_words.extend([src_lo, src_hi, dst_lo, dst_hi, dst_off, source.numel()])
        return

    if source.dim() > 2:
        # Fold the leading dimensions into separate runs so that every run is a
        # plain 1-D/2-D view.
        offset = dst_off
        for index in range(source.shape[0]):
            sub = source[index]
            _append_run(plan_words, sub, dst_addr, offset, False)
            offset += sub.numel()
        return

    src_lo, src_hi = _split_addr(source.data_ptr())
    dst_lo, dst_hi = _split_addr(dst_addr)
    plan_words.extend(
        [
            src_lo,
            src_hi,
            dst_lo,
            dst_hi,
            dst_off,
            source.shape[-1],  # n_cols
            0 if source.dim() == 1 else source.stride(0),  # row stride
            source.stride(-1),  # column stride
            1 if source.dim() == 1 else source.shape[0],  # n_rows
        ]
    )


def _append_zero_run(plan_words, dst_addr, dst_off, size, contiguous):
    """Append a run with a null source address, i.e. a zero-filled slot."""
    dst_lo, dst_hi = _split_addr(dst_addr)
    plan_words.extend([0, 0, dst_lo, dst_hi, dst_off, size])
    if not contiguous:
        # Keep every run of a strided plan the same width.
        plan_words.extend([0, 1, 1])


def _upload_plan(plan_words, device):
    """Pack the int32 plan words into one device buffer (single H2D copy)."""
    return torch.tensor(plan_words, dtype=torch.int32, device=device)


def _copy_grid(total):
    """Persistent-CTA grid for one copy kernel launch."""
    return min(max(total // _COPY_BLOCK + 1, 1), _COPY_GRID_CAP)


def _launch_plan_copy(plan, num_runs, ref_tensor, total):
    """Launch the single copy kernel that materialises the flat buffer."""
    _flat_copy_plan_kernel[(_copy_grid(total),)](
        plan,
        ref_tensor,
        num_runs,
        BLOCK=_COPY_BLOCK,
        num_warps=_COPY_NUM_WARPS,
    )


def _launch_strided_plan_copy(plan, num_runs, ref_tensor, total):
    _strided_copy_plan_kernel[(_copy_grid(total),)](
        plan,
        ref_tensor,
        num_runs,
        BLOCK=_COPY_BLOCK,
        num_warps=_COPY_NUM_WARPS,
    )


def _copy_flat_into(dst, src, total):
    """dst[:total] = src[:total] with the plan kernel (one run, one launch)."""
    if total == 0:
        return
    plan_words = []
    _append_run(plan_words, src, dst.data_ptr(), 0, src.is_contiguous())
    plan = _upload_plan(plan_words, dst.device)
    _launch_plan_copy(plan, 1, dst, total)


def _flatten_weight_impl(
    weight_arr,
    weight_stride0,
    input_size,
    mode,
    hidden_size,
    proj_size,
    num_layers,
    batch_first,
    bidirectional,
    out=None,
):
    if len(weight_arr) == 0:
        raise RuntimeError(
            "copy_weights_to_flat_buf_views: cannot flatten empty weight list"
        )

    weight_arr = list(weight_arr)
    runs, total = _build_copy_plan(
        weight_arr,
        weight_stride0,
        int(input_size),
        int(mode),
        int(hidden_size),
        int(proj_size),
        int(num_layers),
        bool(bidirectional),
    )

    elem_size = weight_arr[0].element_size()
    if elem_size not in _SUPPORTED_ELEM_SIZES:
        raise NotImplementedError(
            "cudnn_rnn_flatten_weight: torch_gcu does not carry 64-bit integers "
            "through the flat weight copy, so "
            f"a {elem_size}-byte weight element size is not supported"
        )

    # The flat buffer is a pure copy, so all weights must share one dtype:
    # rebinding below views the buffer with the buffer's dtype, and the
    # reference implementation rejects mixed dtypes too ("parameter types
    # mismatch").
    dtype = weight_arr[0].dtype
    device = weight_arr[0].device
    for w in weight_arr:
        if w.dtype != dtype:
            raise RuntimeError(
                "cudnn_rnn_flatten_weight: all weights must have the same dtype, "
                f"got {dtype} and {w.dtype}"
            )

    canonical = _canonical_base(weight_arr, runs, total) if total > 0 else None
    if canonical is not None:
        # The weights already view one flat buffer in plan order, so the flat
        # result *is* the input storage: nothing to copy and nothing to rebind.
        # This is the steady state of ``flatten_parameters()``, which runs on
        # every forward, so it has to stay free of device work.
        flat = canonical.as_strided((total,), (1,), 0)
        if out is None:
            return flat
        out.resize_(total)
        with torch_device_fn.device(device):
            _copy_flat_into(out, flat, total)
        return out

    if out is not None and out.dtype != dtype:
        raise RuntimeError(
            "cudnn_rnn_flatten_weight.out: expected out tensor to have "
            f"dtype {dtype}, but got {out.dtype}"
        )

    # The reference ``.out`` overload fills ``out`` from a buffer that the
    # weights are rebound onto, so the weights alias an internal buffer rather
    # than the caller's tensor.  Keep that separation.
    buffer = torch.empty(total, dtype=dtype, device=device)
    if total > 0:
        # One plan, one launch: every weight matrix and bias lands in its slot
        # and every cuDNN-reserved bias slot is zeroed by the same kernel.
        contiguous = all(
            weight_arr[src].is_contiguous() for src, _, _ in runs if src >= 0
        )
        plan_words = []
        for src, dst, size in runs:
            if size == 0:
                continue
            if src < 0:
                # Null source address: the kernel stores zeros for this run.
                _append_zero_run(plan_words, buffer.data_ptr(), dst, size, contiguous)
                continue
            _append_run(plan_words, weight_arr[src], buffer.data_ptr(), dst, contiguous)
        plan = _upload_plan(plan_words, device)
        num_runs = len(plan_words) // (
            _PLAN_WORDS if contiguous else _STRIDED_PLAN_WORDS
        )
        with torch_device_fn.device(device):
            if contiguous:
                _launch_plan_copy(plan, num_runs, buffer, total)
            else:
                _launch_strided_plan_copy(plan, num_runs, buffer, total)

    # Rebind every weight onto the flat buffer, which is the whole point of the
    # operator: the only production caller (``nn.RNNBase.flatten_parameters``)
    # throws the return value away and relies on this side effect.
    _rebind_weights(weight_arr, runs, buffer, total)

    if out is None:
        return buffer
    out.resize_(total)
    with torch_device_fn.device(device):
        _copy_flat_into(out, buffer, total)
    return out


def cudnn_rnn_flatten_weight(
    weight_arr,
    weight_stride0,
    input_size,
    mode,
    hidden_size,
    proj_size,
    num_layers,
    batch_first,
    bidirectional,
):
    logger.debug("GEMS_ENFLAMECUDNN_RNN_FLATTEN_WEIGHT")
    return _flatten_weight_impl(
        weight_arr,
        weight_stride0,
        input_size,
        mode,
        hidden_size,
        proj_size,
        num_layers,
        batch_first,
        bidirectional,
    )


def cudnn_rnn_flatten_weight_out(
    weight_arr,
    weight_stride0,
    input_size,
    mode,
    hidden_size,
    proj_size,
    num_layers,
    batch_first,
    bidirectional,
    *,
    out,
):
    logger.debug("GEMS_ENFLAMECUDNN_RNN_FLATTEN_WEIGHT_OUT")
    return _flatten_weight_impl(
        weight_arr,
        weight_stride0,
        input_size,
        mode,
        hidden_size,
        proj_size,
        num_layers,
        batch_first,
        bidirectional,
        out=out,
    )
